import java.util.*;
class Solution {
  public int lengthOfLIS(int[] nums) {
    List<Integer> dp = new ArrayList<>();
    for (int x : nums) {
      int i = Collections.binarySearch(dp, x);
      if (i < 0) i = -i-1;
      if (i == dp.size()) dp.add(x); else dp.set(i, x);
    }
    return dp.size();
  }
}

