int partition(vector<int>& nums, int l, int r) {
  int pivot = nums[r]; int i = l;
  for (int j=l;j<r;++j) if (nums[j] <= pivot) swap(nums[i++], nums[j]);
  swap(nums[i], nums[r]);
  return i;
}
